<script setup lang="ts">
import AdminResourceManager from '../../components/AdminResourceManager.vue'
definePageMeta({layout:'admin',middleware:'admin'})
const{data:staffData}=await useFetch<{items:Array<{id:string;firstName:string;lastName:string|null;active:boolean}>}>('/api/admin/manage',{query:{resource:'staff'},key:'admin-schedule-staff'})
const staffOptions=computed(()=>[{label:'Horaire commun du salon',value:''},...(staffData.value?.items.filter((item)=>item.active).map((item)=>({label:`${item.firstName} ${item.lastName||''}`,value:item.id}))||[])])
const scheduleFields=computed(()=>[{key:'weekday',label:'Jour (0 dimanche – 6 samedi)',type:'select' as const,required:true,options:[{label:'Dimanche',value:'0'},{label:'Lundi',value:'1'},{label:'Mardi',value:'2'},{label:'Mercredi',value:'3'},{label:'Jeudi',value:'4'},{label:'Vendredi',value:'5'},{label:'Samedi',value:'6'}]},{key:'staffId',label:'Professionnelle',type:'select' as const,nullable:true,options:staffOptions.value},{key:'opensAt',label:'Ouverture',type:'time' as const,required:true},{key:'closesAt',label:'Fermeture',type:'time' as const,required:true},{key:'breakStartsAt',label:'Début de pause',type:'time' as const,nullable:true},{key:'breakEndsAt',label:'Fin de pause',type:'time' as const,nullable:true},{key:'active',label:'Actif',type:'checkbox' as const,defaultValue:true}])
const exceptionFields=computed(()=>[{key:'staffId',label:'Professionnelle',type:'select' as const,nullable:true,options:staffOptions.value},{key:'startsAt',label:'Début (heure du Bénin)',type:'datetime' as const,required:true},{key:'endsAt',label:'Fin (heure du Bénin)',type:'datetime' as const,required:true},{key:'kind',label:'Type',type:'select' as const,required:true,options:[{label:'Fermeture',value:'closed'},{label:'Congé',value:'leave'},{label:'Indisponibilité',value:'blocked'},{label:'Jour férié',value:'holiday'},{label:'Heures supplémentaires',value:'extra_hours'}]},{key:'note',label:'Note',type:'textarea' as const}])
const scheduleColumns=[{key:'weekday',label:'Jour'},{key:'staffId',label:'Professionnelle (UUID)'},{key:'opensAt',label:'Ouverture'},{key:'closesAt',label:'Fermeture'},{key:'breakStartsAt',label:'Pause dès'},{key:'breakEndsAt',label:'Jusqu’à'},{key:'active',label:'Actif'}],exceptionColumns=[{key:'kind',label:'Type'},{key:'staffId',label:'Professionnelle'},{key:'startsAt',label:'Début'},{key:'endsAt',label:'Fin'},{key:'note',label:'Note'}]
useSeoMeta({title:'Horaires — Administration',robots:'noindex,nofollow'})
</script>
<template><div class="schedule-admin"><AdminResourceManager resource="schedules" title="Horaires hebdomadaires" description="Un planning commun et des horaires précis par professionnelle." :fields="scheduleFields" :columns="scheduleColumns"/><AdminResourceManager resource="exceptions" title="Exceptions de calendrier" description="Fermetures, congés, indisponibilités et créneaux exceptionnels." :fields="exceptionFields" :columns="exceptionColumns"/></div></template>
<style scoped>.schedule-admin{display:grid;gap:3rem}</style>
const scheduleFields=computed(()=>[{key:'weekday',label:'Jour (0 dimanche – 6 samedi)',type:'select' as const,numeric:true,required:true,options:[{label:'Dimanche',value:'0'},{label:'Lundi',value:'1'},{label:'Mardi',value:'2'},{label:'Mercredi',value:'3'},{label:'Jeudi',value:'4'},{label:'Vendredi',value:'5'},{label:'Samedi',value:'6'}]},{key:'staffId',label:'Professionnelle',type:'select' as const,nullable:true,options:staffOptions.value},{key:'opensAt',label:'Ouverture',type:'time' as const,required:true},{key:'closesAt',label:'Fermeture',type:'time' as const,required:true},{key:'breakStartsAt',label:'Début de pause',type:'time' as const,nullable:true},{key:'breakEndsAt',label:'Fin de pause',type:'time' as const,nullable:true},{key:'active',label:'Actif',type:'checkbox' as const,defaultValue:true}])
